    "explanation": "Fasciculus gracilis ile fasciculus cuneatus'u ayıran **sulcus intermedius posterior**, yalnızca fasciculus cuneatus'un var olduğu **T6 seviyesinin üzerinde** bulunur; T6 altında görülmez.",
