    "professor": "Belirtilmemiş",
    "question": "Aşağıda belirtilen laboratuar kuralları hangi şıkta doğru olarak verilmiştir? - Kesinlikle asit deneylerinde dikkat edilmeli asit üzerine su yavaş yavaş ilave edilmelidir. - Bazı kimyasallar su ile şiddetli reaksiyon verdiklerinden her türlü madde lavaboya dökülmemelidir. -Test tüplerinde ısıtma yapılırken tüplerin ucu etraftaki kişiler üzerine doğru tutulmamalıdır. - Yakıcı ve tehlikeli maddelerden korunması için laboratuara önlükle gelinmelidir.",
