    "question": "Hiçbir motor defisite bulunmayan deney hayvanında oluşturulan lezyon sonucu hayvan sağ ekstremitesiyle öğrendiğini sol ekstremitesiyle yapamamaktadır. Oluşturulan lezyonun olası yeri hangisidir ?",
