    "question": "Elektroensefalografi (EEG) yönteminde elektrot bağlantı şekilleri ile ilgili verilen;\n1. Unipolar (referans) yöntemde seçilen bir aktif elektrot bölgesinin görece nötr/uzak bir referans noktasına göre potansiyel değişimleri kayıtlanır.\n2. Bipolar yöntemde birbirine yakın iki aktif elektrot bölgesi arasındaki potansiyel farkı gözlenir.\n3. Standart EEG kayıt sistemi uluslararası '10-20' sistemi olarak adlandırılan kafatası çevresindeki elektrot yerleşim bölgelerini içerir.\nbilgilerinden hangileri doğrudur?",
