    "question": "Kliniğe yatışı yapılan hastanın yapılan nörolojik muayenesinde tam konuşma kaybı, konuşma akıcılığı ve tekrarı bozuk fakat anlaması sağlam ise hangi tip afazi gelişmiştir?",
