    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Ses fiziği ile ilgili verilen;\nI. Nesnelerin titreşmesiyle oluşur ve yayılması için maddesel bir ortam gerekir.\nII. Sesin frekansı sesin yüksekliğini (tiz/pes oluşunu) belirler ve birimi Hertz (Hz)'dir.\nIII. Ses boşlukta (vakumda) ışık hızıyla yayılır.\nIV. Sesin şiddeti (gürlüğü) genliği ile ilişkilidir ve desibel (dB) ile ifade edilir.\nbilgilerinden hangisi/hangileri doğrudur?",
