    "q_num": 13,
    "subject": "Anatomi",
    "professor": "Hülya Özdemir",
    "question": "AşağıdakiIerden hangisi assosiasyon yollarından biridir?",
    "options": [
      {
        "letter": "A",
        "text": "Comissura posterior"
      },
      {
        "letter": "B",
        "text": "Corpus callosum"
      },
      {
        "letter": "C",
        "text": "Fasciculus uncinatus"
      },
      {
        "letter": "D",
        "text": "Corona radiata"
      },
      {
        "letter": "E",
        "text": "Capsula interna"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "**Fasciculus uncinatus**, aynı serebral hemisfer içinde frontal lobun alt kısımları ile temporal lobun ön kısımlarını birbirine bağlayan bir **assosiasyon yolağı**dır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
