    "q_num": 14,
    "subject": "Anatomi",
    "professor": "Hülya Özdemir",
    "question": "AşağıdakiIerden hangisi projeksiyon lifidir?",
    "options": [
      {
        "letter": "A",
        "text": "Commissura habenulorum"
      },
      {
        "letter": "B",
        "text": "Capsula interna"
      },
      {
        "letter": "C",
        "text": "Corpus callozum"
      },
      {
        "letter": "D",
        "text": "Capsula ekstrema"
      },
      {
        "letter": "E",
        "text": "Capsula eksterna"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Serebral korteks ile talamus, beyin sapı ve medulla spinalis arasında çift yönlü duyusal ve motor iletiyi sağlayan ana **projeksiyon lif demeti** **capsula interna**'dır.",
    "note": "",
