    "q_num": 17,
    "subject": "Anatomi",
    "professor": "Hülya Özdemir",
    "question": "Nervus maxillaris ( V2 ) ile ilgili aşağıdakilerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Tamamen duyu liflerinden oluşur."
      },
      {
        "letter": "B",
        "text": "Üst dudağı innerve eden"
      },
      {
        "letter": "C",
        "text": "Alın derisinin duyusunu alır."
      },
      {
        "letter": "D",
        "text": "Alt göz kapağını innerve eder."
      },
      {
        "letter": "E",
        "text": "Üst çene derisinin duyusunu alır."
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Alın derisi ve üst göz kapağının duyusal innervasyonu n. ophthalmicus (CN V1) tarafından sağlanır; **nervus maxillaris (CN V2)** ise alt göz kapağı, burun kanadı, yanak ve üst dudağı innerve eder.",
    "note": "",
