    "explanation": "**Koku duyusu**, talamik röleye uğramadan doğrudan primer kortekse ulaşan tek duyudur; nucleus ventralis posteromedialis (VPM) ise tat ve yüz duyu yollarının talamik çekirdeğidir.",
