    "professor": "M. Haluk Uluutku",
    "question": "Kornea refleksi alınamayan bir hastanın nörolojik muayenesinde göz küresi hareketlerinin normal olduğu saptanmıştır. Bu hastadaki lezyon aşağıdaki sinirlerin hangisindedir?",
