    "question": "İki ay önce trafik kazası geçiren erkek hastanın fizik muayenesinde, sol göz görme alanının medial yarısı (nasal) ile sağ göz görme alanının lateral yarısının (temporal) tamamında görme kaybı tespit ediliyor. Bu hastada görme yollarının hangi bölgesinde hasar en olasıdır?",
