    "open_answer": "",
    "explanation": "Sol nasal görme alanı sol temporal retinaya, sağ temporal görme alanı sağ nasal retinaya düşer; bu liflerin birlikte seyrettiği **sol tractus opticus** hasarında sağ homonim hemianopsi oluşur.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
