    "open_answer": "",
    "explanation": "Yenidoğan döneminde medulla spinalis (conus medullaris) yaklaşık **L3 vertebra** seviyesinde sonlanır; erişkinde ise vertebral kolonun daha hızlı büyümesiyle **L1-L2 vertebra** arasına çekilir.",
