    "professor": "Sinan Yürüker",
    "question": "Aşağıdaki hangisi serebral hemisferlerin iki loba tam olarak ayrılamaması sonucu oluşan ve ileri derecede fasiyal anomalilerle karakterize gelişimsel bir defekttir?",
