    "question": "İşitme ile ilgili verilen bilgilerden hangisi doğru değildir?",
    "options": [
      {
        "letter": "A",
        "text": "Skala media içerisinde bulunan sıvı yüksek potasyum (K+) ve düşük sodyum (Na+) konsantrasyonuna sahip olup perilenf olarak adlandırılır."
      },
      {
        "letter": "B",
        "text": "Corti organındaki titreşimle tüy hücrelerinin silyumlarının bükülmesi tüy hücre membranında K + iletkenliğinde değişime neden olur."
      },
      {
        "letter": "C",
        "text": "Empedans eşleştirme,tjmpanik zarının yüzey alanıyla oval pencerenin yüzey alanıarasındaki oran ve kemikçiklerden oluşan kaldıraç sistemi ile gerçekleşir."
      },
      {
        "letter": "D",
        "text": "Tüy hücreleri hiperpolarize olduğunda glutamat salınımı azalır."
      },
      {
        "letter": "E",
        "text": "işitsel transdüksiyonun gerçekleşebilmesi içi havada ilerleyen ses dalgalarının sıvıda basınç dalgalarına dönüştürülmesi gerekmektedir."
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Scala media içinde yer alan ve stria vascularis tarafından üretilen K⁺ zengini sıvı perilenf değil, **endolenf**tir; perilenf ise Na⁺ zengin olup scala vestibuli ve scala tympani boşluklarını doldurur.",
