    "question": "İnsan dış kulak kanalı yaklaşık 2,7 cm uzunluklu bir ucu kapalı silindirik bir boruya benzetilir, sesin havadaki yayılma hızı 340 m/s ise bu kanalın temel frekansındaki rezonansı hesaplayınız?",
