    "explanation": "Ardışık ve karmaşık hareketlerin korteksle birlikte önceden planlanması ve zamanlanması serebroserebelluma aittir; **spinoserebellum** ise hareket anında yürütme ve koordinasyonu kontrol eder.",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
