    "subject": "Biyokimya",
    "professor": "Soycan Mızrak",
    "question": "Alınan beyin omiirilik sıvısının, santrifüj edilince oluşan supernatantında pembe bir ksantromik görünüm mevcut ise hangisi ön planda düşünülmelidir?",
