    "professor": "Hilmiye Pakyürek",
    "question": "Bulbus olfaktoryusta bulunan hücrelerden hangisi /hangileri glutamat salgılayan eksitatör projeksiyon nöronlarıdır? I- Mitral hücreler                                      II- Granül hücreleri III- Püskülsü hücreler                              IV- Periglomerüler hücreler",
