    "explanation": "Özel somatik afferent (ÖSA / SSA) lifler çevre ortamdan alınan özel duyuları iletir; bunlar **görme duyusu (II - N. opticus)** ile **işitme ve denge duyusudur (III - N. vestibulocochlearis)**.",
