    "q_num": 88,
    "subject": "Histoloji ve Embriyoloji",
    "professor": "Hasan Asker",
    "question": "Timpanik membranda beyaz kistik bir yapıDış kulak gelişimi sırasında meatal tıkaçın kalıcıdırTüpün kanalizasyonunun gelişememesidirGebeliğin 33. haftasında kaybolması beklenirken anomalilerinden hangisi doğrudur?",
