    "professor": "Serçin Özlem Çalışkan",
    "question": "Elektroensefalografi yöntemi ile ilgili verilen bilgilerden hangisi/hangileri doğrudur? I. Seçilen bir elektrot bölgesinin uzak bir referans noktasına göre potansiyel değişimlerinin kayıtlanması II. EEG sinyalinin genliği nöronların aktivitesini nasıl senkron olduğuna bağlıdır. III. Sinaptik aktivitenin eksitatör yada inhibitör olmasına göre post sinaptik hücre zarı depolarize ve IV. Bipolar çift muz montajı ensefalitlerin tanısında duyarlı bir bağlantı şeklidir. V. EEG aktivitesinin kaynağını oluşturduğu düşünülen başlıca mekanizma ‘sinaptik elektrogenesiztir'. VI. Derin uyku, genel anestezi, koma, dikkat eksikliğin teta dalgaları gözükür.",
