    "explanation": "PICA tıkanmasında gelişen **Wallenberg sendromunda**; nuc. ambiguus hasarı disfaji ve disfoniye, nuc. spinalis n. trigemini hasarı aynı taraf yüzde ağrı-ısı kaybına, nuc. solitarius hasarı ise tat duyusu kaybına neden olur.",
