    "explanation": "Serebellum derin çekirdekleri lateralden mediale doğru **nucleus dentatus**, **nucleus emboliformis**, **nucleus globosus** ve **nucleus fastigii**'dir. **Nucleus ruber** ise mesencephalon tegmentumunda yer alan bir çekirdektir.",
