    "open_answer": "Sulcus anterolateralis (ön köklerin çıktığı yer) ve Sulcus posterolateralis (arka köklerin girdiği yer). • İstisna Detayı:Sulcus intermedius posterior sadece T6 ve üzerinde (Fasciculus gracilis ve cuneatus'u ayırmak için) bulunur, alt segmentlerde yoktur. 11. 12. 13. Medulla spinalis arka boynuz (gri cevher) nükleusları ve lamina eşleşmeleri: • Nuc. marginalis (Lamina I): Ağrı-ısı duyusunun ilk giriş yeridir. • Nuc. proprius (Lamina III-IV): Pozisyon, hareket ve hafif dokunma duyularını alır. • Nuc. thoracicus (Clarke çekirdeği - Lamina VII): C8-L3 arasında bulunur, şuuraltı propriyosepsiyonu beyinciğe taşıyan yolun (Tractus spinocerebellaris posterior) orijinidir.",
    "explanation": "Medulla spinalis boyunca ön motor köklerin çıktığı **sulcus anterolateralis** ile arka duyu köklerinin girdiği **sulcus posterolateralis** tüm segmentlerde bulunur; sulcus intermedius posterior ise yalnızca T6 üzerinde yer alır.",
