    "answer": "E",
    "open_answer": "Hasarın karşı tarafında (kontralateral) spastik felç (Üst motor nöron hasarı bulguları).",
    "explanation": "Üst motor nöronlardan inen tractus corticospinalis lateralis liflerinin yaklaşık %85-90'ı bulbusun alt sınırındaki **decussatio pyramidalis**'te karşı tarafa çapraz yapar; bu çaprazın yukarısındaki (korteks, kapsüla interna, mezensefalon, pons veya üst bulbus) tek taraflı bir lezyonda hasarın **karşı tarafında (kontralateral) spastik felç**, hiperrefleksi ve Babinski pozitifliği görülür (E doğru). Flask (gevşek) felç ve fasikülasyonlar üst motor nöron lezyonunun değil, medulla spinalis ön boynuz veya periferik sinirdeki **alt motor nöron** hasarının belirtileridir (A yanlış). İpsilateral (aynı tarafta) spastik felç decussatio pyramidalis'in yukarısındaki değil, çaprazın altındaki (medulla spinalis seviyesindeki) tractus corticospinalis hasarlarında ortaya çıkar (B yanlış). Bilateral flask paralizi ve belirgin kas atrofisi tek taraflı suprapiramidal kortikospinal hasarda değil, her iki taraf ön boynuz hücrelerinin yaygın alt motor nöron hastalıklarında görülür (C yanlış). Saf kortikospinal yol lezyonları motor fonksiyonu bozar; aynı tarafta tam duyu kaybı ve arefleksiye yol açmaz (D yanlış).",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
